// swift-tools-version:5.7
// Lets the platform-independent core in Shared/ be tested with `swift test` on macOS (or Linux).
// The Xcode project (generated by XcodeGen from project.yml) compiles the same sources into the app and extension.
import PackageDescription

let package = Package(
    name: "RegBoardCore",
    platforms: [.iOS(.v16), .macOS(.v12)],
    products: [.library(name: "RegBoardCore", targets: ["RegBoardCore"])],
    targets: [
        .target(name: "RegBoardCore", path: "Shared"),
        .testTarget(name: "RegBoardCoreTests", dependencies: ["RegBoardCore"], path: "Tests"),
    ]
)
